// Inline functions: the module compiled these into each caller
namespace D2Game { namespace Seed {
#ifndef D2_DEFINED_INLINE_00472280
#define D2_DEFINED_INLINE_00472280
__declspec(noinline) inline int32_t __fastcall RollBetweenMinAndMax(D2SeedStrc * pSeed, int32_t nMin, uint32_t nMax) {
    uint32_t sNewSeed;
    if ((int)nMax <= 0) {
      return nMin;
    }
    if (nMax & nMax - 1) {
      sNewSeed = D2_SeedRoll(pSeed);
      return (int)(sNewSeed % nMax) + nMin;
    }

    sNewSeed = D2_SeedRoll(pSeed);
    return (nMax - 1 & sNewSeed) + nMin;
}
#endif // D2_DEFINED_INLINE_00472280
#ifndef D2_DEFINED_INLINE_004bc500
#define D2_DEFINED_INLINE_004bc500
__declspec(noinline) inline int32_t __fastcall SEED_RollRange(D2SeedStrc * pSeed, int32_t nMin, int32_t nMax) {
    uint32_t dSeedResult;
    if (nMax <= nMin) {
      return nMin;
    }

    uint32_t nRangeWidth = nMax - nMin;
    if (nRangeWidth & nRangeWidth - 1) {
      dSeedResult = D2_SeedRoll(pSeed);
      return (int)(dSeedResult % nRangeWidth) + nMin;
    }

    dSeedResult = D2_SeedRoll(pSeed);
    return (nRangeWidth - 1 & dSeedResult) + nMin;
}
#endif // D2_DEFINED_INLINE_004bc500
#ifndef D2_DEFINED_INLINE_004cc790
#define D2_DEFINED_INLINE_004cc790
__declspec(noinline) inline int32_t __fastcall SEED_RollRangeInclusive(D2SeedStrc * pSeed, int32_t nMinValue, int32_t nMaxValue) {
    if (nMinValue >= nMaxValue) {
      return nMinValue;
    }

    uint32_t nRandResult = D2Common::Seed::RANDOM_RandomNumberSelector(pSeed, nMaxValue - nMinValue + 1);
    return nRandResult + nMinValue;
}
#endif // D2_DEFINED_INLINE_004cc790
}} // namespace D2Game::Seed
